using System;
using System.Collections.Generic;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;

namespace VectorFit {
    static class GameMath {
        public static double HorizontalFov(double vertical,double aspect){if(vertical<=0||vertical>=180||aspect<=0||Double.IsNaN(vertical)||Double.IsNaN(aspect)||Double.IsInfinity(aspect))throw new ArgumentException("Invalid FOV");return 360/Math.PI*Math.Atan(Math.Tan(vertical*Math.PI/360)*aspect);}
        public static double Sensitivity(double current,double currentCm,double desiredCm){if(current<=0||currentCm<=0||desiredCm<=0||Double.IsNaN(current+currentCm+desiredCm)||Double.IsInfinity(current+currentCm+desiredCm))throw new ArgumentException("Invalid sensitivity");return current*currentCm/desiredCm;}
        public static double Distance(long counts,double dpi){if(dpi<100||dpi>50000||Double.IsNaN(dpi))throw new ArgumentException("Invalid DPI");return Math.Abs((double)counts)*2.54/dpi;}
    }
    class GameSetupForm:Form {
        NumericUpDown dpi,desired,horizontal,currentCm,currentSens,vertical,width,height;Label suggestion;Action checkInput;
        public double Dpi{get{return (double)dpi.Value;}} public double Cm360{get{return (double)desired.Value;}} public double Hfov{get{return (double)horizontal.Value;}}
        static string T(string nb,string en){return L.English?en:nb;}
        public GameSetupForm(Setup setup,Action check) {
            checkInput=check;Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);Text=T("TrueTrack | Spilloppsett","TrueTrack | Game setup");ClientSize=new Size(760,680);MinimumSize=new Size(780,600);StartPosition=FormStartPosition.CenterParent;BackColor=Color.FromArgb(19,24,27);ForeColor=Color.FromArgb(237,244,242);Font=new Font("Segoe UI",10);AutoScaleMode=AutoScaleMode.None;
            var p=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(24)};Controls.Add(p);
            Action<string> note=s=>p.Controls.Add(new Label{Text=s,Width=680,AutoSize=true,MaximumSize=new Size(680,0),MinimumSize=new Size(680,45),Margin=new Padding(0,0,0,10)});
            note(T("Bruk samme DPI og synsfelt som i spillet. Større cm/360 betyr lavere følsomhet. Alt her er valgfritt. Endringene brukes ved neste nye baseline.","Match your game's DPI and field of view. Higher cm/360 means lower sensitivity. Everything here is optional. Changes apply to your next new baseline."));
            dpi=Field(p,T("DPI på musen","Mouse DPI"),setup.Dpi,100,50000,0);desired=Field(p,T("Ønsket avstand for 360° (cm)","Desired distance for 360° (cm)"),setup.Cm360,3,200,2);horizontal=Field(p,T("Horisontalt synsfelt (grader)","Horizontal field of view (degrees)"),setup.Hfov,60,140,2);
            var defaults=new Button{Text=T("Ingen preferanse? Bruk 40 cm/360 og 103° FOV","No preference? Use 40 cm/360 and 103° FOV"),Width=680,Height=38};defaults.Click+=delegate{desired.Value=40;horizontal.Value=103;};p.Controls.Add(defaults);
            note(T("40 cm/360 og 103° er utgangspunkter, ikke optimale verdier for alle. DPI bør samsvare med musen. Du kan hoppe over blindmålingen og omregningene.","40 cm/360 and 103° are starting points, not universal optima. DPI should match your mouse. You can skip the blind measurement and conversions."));
            note(T("Ingen FOV er best for alle. Kopier spillets faktiske horisontale FOV. Oppløsning alene gir ikke riktig verdi. Hold FOV og skalering faste under sammenligning.","There is no universally best FOV. Match the game's actual horizontal FOV. Resolution alone cannot determine it. Keep FOV and scaling fixed during comparisons."));
            note(T("Lik cm/360 gir lik fysisk rotasjon, men ulik FOV gir ulik bevegelse på skjermen. Bruk cm/360 uten driverkorreksjon som grunnverdi; en aktiv global profil må ikke regnes inn to ganger.","Equal cm/360 matches physical rotation, but different FOV changes motion on screen. Use cm/360 without driver correction as the base value; do not count an active global profile twice."));
            var conversion=new GroupBox{Text=T("Har spillet vertikalt FOV? Konverter her","Does your game use vertical FOV? Convert here"),Width=680,Height=145,ForeColor=ForeColor};var cp=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(8,20,8,0)};conversion.Controls.Add(cp);p.Controls.Add(conversion);
            vertical=Small(cp,"vFOV",74,1,170);width=Small(cp,T("Bredde","Width"),1920,320,16000);height=Small(cp,T("Høyde","Height"),1080,200,16000);
            var convert=new Button{Text=T("Bruk beregnet FOV","Use converted FOV"),Width=210,Height=34};cp.Controls.Add(convert);convert.Click+=delegate{double h=GameMath.HorizontalFov((double)vertical.Value,(double)(width.Value/height.Value));if(h<60||h>140){MessageBox.Show(this,T("Beregnet FOV er utenfor testens område 60–140°.","Calculated FOV is outside the test range of 60–140°."));return;}horizontal.Value=(decimal)h;};
            note(T("Konverteringen forutsetter vanlig perspektiv og at spillet bruker dette sideforholdet. Strukket bilde eller spill som bruker en 4:3-referanse må håndteres i spillets egne innstillinger.","Conversion assumes standard perspective and that the game uses this aspect ratio. Stretched images or games using a 4:3 reference require checking the game's own settings."));
            currentCm=Field(p,T("Nåværende målt cm/360 i spillet","Current measured in-game cm/360"),setup.Cm360,3,200,2);currentSens=Field(p,T("Nåværende følsomhetstall i spillet","Current in-game sensitivity value"),1,0.0001m,10000,4);
            suggestion=new Label{Width=680,AutoSize=true,MaximumSize=new Size(680,0),MinimumSize=new Size(680,65)};p.Controls.Add(suggestion);EventHandler refresh=delegate{suggestion.Text=T("Forslag til spillets følsomhet: ","Suggested in-game sensitivity: ")+GameMath.Sensitivity((double)currentSens.Value,(double)currentCm.Value,Cm360).ToString("0.####")+T("\nGjelder samme DPI, uendret driverskalering og ingen akselerasjon. Skriv tallet inn i spillet selv.","\nAssumes unchanged DPI, unchanged driver scaling and no acceleration. Enter this value in the game yourself.");};currentCm.ValueChanged+=refresh;currentSens.ValueChanged+=refresh;desired.ValueChanged+=refresh;refresh(null,EventArgs.Empty);
            var blind=new Button{Text=T("Finn ønsket cm/360 med blindmåling","Find preferred cm/360 with a blind measurement"),Width=680,Height=40};p.Controls.Add(blind);blind.Click+=delegate{try{checkInput();string err;string before=Driver.TryRead(out err);string fingerprint=Driver.Fingerprint(before);using(var f=new BlindDistanceForm(Dpi)){if(f.ShowDialog(this)!=DialogResult.OK)return;checkInput();string after=Driver.TryRead(out err);if(fingerprint!=Driver.Fingerprint(after))throw new Exception(T("Driveroppsettet endret seg. Gjenta målingen.","Driver settings changed. Repeat the measurement."));desired.Value=(decimal)f.Result;}}catch(Exception e){MessageBox.Show(this,e.Message,"TrueTrack");}};
            note(T("Blindmålingen anslår håndbevegelsen du ønsker for én rotasjon. Den leser ikke rotasjonen i et spill. Kontroller resultatet med linjal i spillet.","The blind measurement estimates your preferred hand travel for one turn. It cannot read a game's rotation. Verify the result with a ruler in-game."));
            var buttons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=60,Padding=new Padding(24,8,0,0)};var save=new Button{Text=T("Bruk oppsett","Use setup"),Width=200,Height=38,DialogResult=DialogResult.OK};var cancel=new Button{Text=T("Hopp over","Skip"),Width=150,Height=38,DialogResult=DialogResult.Cancel};buttons.Controls.Add(save);buttons.Controls.Add(cancel);Controls.Add(buttons);CancelButton=cancel;
        }
        NumericUpDown Field(FlowLayoutPanel p,string label,double value,decimal min,decimal max,int decimals){var row=new Panel{Width=680,Height=40};row.Controls.Add(new Label{Text=label,AutoSize=true,Location=new Point(0,8)});var n=new NumericUpDown{Minimum=min,Maximum=max,DecimalPlaces=decimals,Value=(decimal)value,Width=160,Location=new Point(490,3)};row.Controls.Add(n);p.Controls.Add(row);return n;}
        NumericUpDown Small(FlowLayoutPanel p,string label,decimal value,decimal min,decimal max){p.Controls.Add(new Label{Text=label,AutoSize=true,Margin=new Padding(0,8,4,0)});var n=new NumericUpDown{Minimum=min,Maximum=max,Value=value,Width=95};p.Controls.Add(n);return n;}
    }
    class BlindDistanceForm:Form {
        double dpi;bool captured,measuring,paused;long x;IntPtr device;List<double> samples=new List<double>();public double Result;string notice="";
        static string T(string nb,string en){return L.English?en:nb;}
        public BlindDistanceForm(double d){dpi=d;Text="TrueTrack";ClientSize=new Size(880,540);StartPosition=FormStartPosition.CenterParent;BackColor=Color.FromArgb(19,24,27);ForeColor=Color.FromArgb(237,244,242);DoubleBuffered=true;KeyPreview=true;Shown+=delegate{CaptureInput();};Deactivate+=delegate{if(captured){measuring=false;x=0;paused=true;ReleaseInput();Invalidate();}};FormClosed+=delegate{ReleaseInput();};KeyDown+=delegate(object s,KeyEventArgs e){if(e.KeyCode==Keys.Escape)Close();else if(e.KeyCode==Keys.Space&&paused){paused=false;CaptureInput();Invalidate();}else if(e.KeyCode==Keys.Enter&&samples.Count==5&&Result>=3&&Result<=200){DialogResult=DialogResult.OK;Close();}};}
        void CaptureInput(){Native.Register(Handle,true);captured=true;Cursor.Clip=RectangleToScreen(ClientRectangle);Cursor.Hide();}
        void ReleaseInput(){if(!captured)return;captured=false;Cursor.Clip=Rectangle.Empty;Cursor.Show();Native.Register(Handle,false);}
        protected override void WndProc(ref Message m){if(m.Msg==0xFF&&captured){IntPtr dev;int dx,dy;ushort buttons;bool absolute;if(Native.Read(m.LParam,out dev,out dx,out dy,out buttons,out absolute)&&!absolute){if(device==IntPtr.Zero&&(buttons&1)!=0)device=dev;if(dev==device){if(measuring)x+=dx;if((buttons&1)!=0&&samples.Count<5){if(!measuring){x=0;measuring=true;notice="";}else{double cm=GameMath.Distance(x,dpi);measuring=false;if(cm>=3&&cm<=200)samples.Add(cm);else notice=T("Avstanden må være 3–200 cm. Prøv igjen.","Distance must be 3–200 cm. Try again.");if(samples.Count==5){Result=Analysis.Median(samples);ReleaseInput();}Invalidate();}}}}}base.WndProc(ref m);}
        protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);string text=paused?T("Pause. Uferdig måling er forkastet.\nTrykk mellomrom for å fortsette.","Paused. Incomplete measurement discarded.\nPress Space to continue."):samples.Count==5?T("Blindmåling fullført","Blind measurement complete")+"\n\n"+Result.ToString("0.0")+" cm / 360°\n"+T("Median av fem forsøk. Spenn: ","Median of five attempts. Range: ")+samples.Min().ToString("0.0")+"–"+samples.Max().ToString("0.0")+" cm\n\n"+T("Trykk Enter for å bruke anslaget. Esc avbryter.","Press Enter to use this estimate. Esc cancels."):T("Blindmåling ","Blind measurement ")+(samples.Count+1)+" / 5\n\n"+(measuring?T("Flytt musen vannrett så langt du ønsker for 360°.\nKlikk når du er ferdig. Ikke løft musen.","Move horizontally as far as you want for a 360° turn.\nClick when done. Do not lift the mouse."):T("Plasser musen slik at du har plass. Klikk for å starte.\nIngen bevegelsesbane vises. Bruk samme mus i alle forsøk.","Position your mouse with room to move. Click to start.\nNo trace is shown. Use the same mouse for all attempts."))+"\n\n"+notice;using(var f=new Font("Segoe UI",19))using(var b=new SolidBrush(ForeColor))using(var fmt=new StringFormat{Alignment=StringAlignment.Center,LineAlignment=StringAlignment.Center})e.Graphics.DrawString(text,f,b,new RectangleF(30,20,ClientSize.Width-60,ClientSize.Height-40),fmt);}
    }
}
